CREATE TYPE "SellerRiskPolicy" AS ENUM ('AUTOMATIC','HIGH_RISK_HOLD');
CREATE TYPE "SellerMaturity" AS ENUM ('NEW','STANDARD','HIGH_RISK');
CREATE TYPE "OrderGroupKind" AS ENUM ('MARKETPLACE','CJ_PLATFORM');
CREATE TYPE "SellerTransferStatus" AS ENUM ('WAITING_FOR_SHIPMENT','RESERVE_PERIOD','READY','SUBMITTING','TRANSFERRED','RETRYABLE','MANUAL_ACTION_REQUIRED','REVERSED','CANCELLED');
CREATE TYPE "RefundOperationStatus" AS ENUM ('REQUESTED','APPROVED','PROCESSING','PARTIALLY_COMPLETED','COMPLETED','RETRYABLE','MANUAL_ACTION_REQUIRED','REJECTED','CANCELLED');
CREATE TYPE "RefundAllocationStatus" AS ENUM ('REQUESTED','APPROVED','PROCESSING','COMPLETED','RETRYABLE','MANUAL_ACTION_REQUIRED','REJECTED','CANCELLED');
CREATE TYPE "RestockStatus" AS ENUM ('NOT_APPLICABLE','AWAITING_RETURN','RETURN_RECEIVED','INSPECTION_REQUIRED','RESTOCKABLE','RESTOCKED','NON_RESTOCKABLE');
ALTER TABLE "Store" ADD COLUMN "marketplaceActivatedAt" TIMESTAMP(3),ADD COLUMN "sellerRiskPolicy" "SellerRiskPolicy" NOT NULL DEFAULT 'AUTOMATIC',ADD COLUMN "riskHoldReason" VARCHAR(500),ADD COLUMN "riskHoldSetAt" TIMESTAMP(3),ADD COLUMN "riskHoldSetById" TEXT,ADD COLUMN "legacyStandardOverrideAt" TIMESTAMP(3),ADD COLUMN "legacyStandardOverrideById" TEXT,ADD COLUMN "legacyStandardOverrideReason" VARCHAR(1000);
UPDATE "Store" s SET "marketplaceActivatedAt"=COALESCE((SELECT MIN(COALESCE(o."paidAt",o."createdAt")) FROM "Order" o JOIN "OrderItem" oi ON oi."orderId"=o.id JOIN "Product" p ON p.id=oi."productId" WHERE p."storeId"=s.id AND o.status NOT IN ('PENDING','CANCELLED') AND (o."paidAt" IS NOT NULL OR o."stripePaymentIntentId" IS NOT NULL)),CURRENT_TIMESTAMP);
CREATE TABLE "OrderGroup" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL,"groupKey" VARCHAR(200) NOT NULL,"kind" "OrderGroupKind" NOT NULL,"storeId" TEXT,"storeIdSnapshot" TEXT,"storeNameSnapshot" TEXT,"storeSnapshot" JSONB,"maturitySnapshot" "SellerMaturity" NOT NULL,"maturityEvidence" JSONB NOT NULL,"stripeConnectedAccountId" TEXT,"itemSubtotalMinor" INTEGER NOT NULL,"shippingAmountMinor" INTEGER NOT NULL,"platformFeeAmountMinor" INTEGER NOT NULL,"sellerNetAmountMinor" INTEGER NOT NULL,"refundedMerchandiseMinor" INTEGER NOT NULL DEFAULT 0,"refundedShippingMinor" INTEGER NOT NULL DEFAULT 0,"commissionReversedMinor" INTEGER NOT NULL DEFAULT 0,"sellerRecoveredMinor" INTEGER NOT NULL DEFAULT 0,"shippingMethod" TEXT,"shippingEstimatedMinDays" INTEGER,"shippingEstimatedMaxDays" INTEGER,"shippingPolicySnapshot" JSONB,"transferStatus" "SellerTransferStatus" NOT NULL DEFAULT 'WAITING_FOR_SHIPMENT',"transferIdempotencyKey" VARCHAR(200),"stripeTransferId" TEXT,"transferAttemptCount" INTEGER NOT NULL DEFAULT 0,"nextTransferAttemptAt" TIMESTAMP(3),"transferErrorCode" VARCHAR(120),"transferErrorMessage" VARCHAR(500),"shipmentVerifiedAt" TIMESTAMP(3),"transferEligibleAt" TIMESTAMP(3),"transferredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
ALTER TABLE "OrderItem" ADD COLUMN "orderGroupId" TEXT;
CREATE TABLE "RefundOperation" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL,"buyerId" TEXT NOT NULL,"status" "RefundOperationStatus" NOT NULL DEFAULT 'REQUESTED',"reason" VARCHAR(1000) NOT NULL,"stripeRefundId" TEXT,"refundIdempotencyKey" VARCHAR(200) NOT NULL,"merchandiseAmountMinor" INTEGER NOT NULL DEFAULT 0,"shippingAmountMinor" INTEGER NOT NULL DEFAULT 0,"totalAmountMinor" INTEGER NOT NULL DEFAULT 0,"reviewedById" TEXT,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "RefundGroupAllocation" ("id" TEXT PRIMARY KEY,"refundOperationId" TEXT NOT NULL,"orderGroupId" TEXT NOT NULL,"status" "RefundAllocationStatus" NOT NULL DEFAULT 'REQUESTED',"merchandiseAmountMinor" INTEGER NOT NULL,"shippingAmountMinor" INTEGER NOT NULL DEFAULT 0,"commissionReversalMinor" INTEGER NOT NULL,"sellerRecoveryMinor" INTEGER NOT NULL,"shippingRefundReason" VARCHAR(500),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "RefundItemAllocation" ("id" TEXT PRIMARY KEY,"refundOperationId" TEXT NOT NULL,"orderItemId" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"unitAmountMinor" INTEGER NOT NULL,"merchandiseAmountMinor" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "TransferReversal" ("id" TEXT PRIMARY KEY,"orderGroupId" TEXT NOT NULL,"refundGroupAllocationId" TEXT NOT NULL,"amountMinor" INTEGER NOT NULL,"idempotencyKey" VARCHAR(200) NOT NULL,"stripeReversalId" TEXT,"status" "RefundAllocationStatus" NOT NULL DEFAULT 'REQUESTED',"attemptCount" INTEGER NOT NULL DEFAULT 0,"errorMessage" VARCHAR(500),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "InventoryRestockEvent" ("id" TEXT PRIMARY KEY,"refundOperationId" TEXT NOT NULL,"orderItemId" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"status" "RestockStatus" NOT NULL,"reason" VARCHAR(120) NOT NULL,"idempotencyKey" VARCHAR(200) NOT NULL,"decidedById" TEXT,"decidedAt" TIMESTAMP(3),"restoredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "OrderGroup_orderId_groupKey_key" ON "OrderGroup"("orderId","groupKey");CREATE UNIQUE INDEX "OrderGroup_transferIdempotencyKey_key" ON "OrderGroup"("transferIdempotencyKey");CREATE UNIQUE INDEX "OrderGroup_stripeTransferId_key" ON "OrderGroup"("stripeTransferId");CREATE INDEX "OrderGroup_storeId_transferStatus_idx" ON "OrderGroup"("storeId","transferStatus");CREATE INDEX "OrderGroup_transferStatus_nextTransferAttemptAt_idx" ON "OrderGroup"("transferStatus","nextTransferAttemptAt");CREATE INDEX "OrderItem_orderGroupId_idx" ON "OrderItem"("orderGroupId");CREATE UNIQUE INDEX "RefundOperation_stripeRefundId_key" ON "RefundOperation"("stripeRefundId");CREATE UNIQUE INDEX "RefundOperation_refundIdempotencyKey_key" ON "RefundOperation"("refundIdempotencyKey");CREATE INDEX "RefundOperation_buyerId_createdAt_idx" ON "RefundOperation"("buyerId","createdAt");CREATE UNIQUE INDEX "RefundGroupAllocation_refundOperationId_orderGroupId_key" ON "RefundGroupAllocation"("refundOperationId","orderGroupId");CREATE UNIQUE INDEX "RefundItemAllocation_refundOperationId_orderItemId_key" ON "RefundItemAllocation"("refundOperationId","orderItemId");CREATE INDEX "RefundItemAllocation_orderItemId_idx" ON "RefundItemAllocation"("orderItemId");CREATE UNIQUE INDEX "TransferReversal_idempotencyKey_key" ON "TransferReversal"("idempotencyKey");CREATE UNIQUE INDEX "TransferReversal_stripeReversalId_key" ON "TransferReversal"("stripeReversalId");CREATE UNIQUE INDEX "TransferReversal_refundGroupAllocationId_orderGroupId_key" ON "TransferReversal"("refundGroupAllocationId","orderGroupId");CREATE UNIQUE INDEX "InventoryRestockEvent_idempotencyKey_key" ON "InventoryRestockEvent"("idempotencyKey");CREATE INDEX "InventoryRestockEvent_orderItemId_status_idx" ON "InventoryRestockEvent"("orderItemId","status");
ALTER TABLE "OrderGroup" ADD CONSTRAINT "OrderGroup_orderId_fkey" FOREIGN KEY("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "OrderGroup" ADD CONSTRAINT "OrderGroup_storeId_fkey" FOREIGN KEY("storeId") REFERENCES "Store"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderGroupId_fkey" FOREIGN KEY("orderGroupId") REFERENCES "OrderGroup"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "RefundOperation" ADD CONSTRAINT "RefundOperation_orderId_fkey" FOREIGN KEY("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "RefundGroupAllocation" ADD CONSTRAINT "RefundGroupAllocation_refundOperationId_fkey" FOREIGN KEY("refundOperationId") REFERENCES "RefundOperation"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "RefundGroupAllocation" ADD CONSTRAINT "RefundGroupAllocation_orderGroupId_fkey" FOREIGN KEY("orderGroupId") REFERENCES "OrderGroup"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "RefundItemAllocation" ADD CONSTRAINT "RefundItemAllocation_refundOperationId_fkey" FOREIGN KEY("refundOperationId") REFERENCES "RefundOperation"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "RefundItemAllocation" ADD CONSTRAINT "RefundItemAllocation_orderItemId_fkey" FOREIGN KEY("orderItemId") REFERENCES "OrderItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "TransferReversal" ADD CONSTRAINT "TransferReversal_orderGroupId_fkey" FOREIGN KEY("orderGroupId") REFERENCES "OrderGroup"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "TransferReversal" ADD CONSTRAINT "TransferReversal_refundGroupAllocationId_fkey" FOREIGN KEY("refundGroupAllocationId") REFERENCES "RefundGroupAllocation"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "InventoryRestockEvent" ADD CONSTRAINT "InventoryRestockEvent_refundOperationId_fkey" FOREIGN KEY("refundOperationId") REFERENCES "RefundOperation"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "InventoryRestockEvent" ADD CONSTRAINT "InventoryRestockEvent_orderItemId_fkey" FOREIGN KEY("orderItemId") REFERENCES "OrderItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
